import json

def summarize_json(filepath):
    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            data = json.load(f)

        summary = {}
        for entry in data:
            hw = entry.get('headword_norm', '')
            if hw not in summary:
                summary[hw] = []
            if len(summary[hw]) < 5:  # limit to 5 per headword for brevity
                summary[hw].append({
                    'id': entry.get('entry_id'),
                    'hw': entry.get('headword'),
                    'def': entry.get('definitions_text', '')[:200] + '...' if len(entry.get('definitions_text', '')) > 200 else entry.get('definitions_text', ''),
                    'dict': entry.get('dict_name_ar'),
                    'en': entry.get('translation_en', '')
                })

        for hw, entries in summary.items():
            print(f"=== {hw} ===")
            for e in entries:
                if e['en']:
                    print(f"  [{e['id']}] {e['hw']} ({e['dict']}): {e['en']}")
                else:
                    print(f"  [{e['id']}] {e['hw']} ({e['dict']}): {e['def']}")
    except Exception as e:
        print(f"Error: {e}")

if __name__ == '__main__':
    print("--- query1.json ---")
    summarize_json('/workspace/query1.json')
